#define AHEAP_CAP 9072
#define LM_CAP_BYTES 36288
#define AHEAP_PHYS 1048576
#define LMEM_CAP 8388608
static int64_t AHEAP[AHEAP_PHYS];
static unsigned char LMEM[LMEM_CAP];
static int64_t AHP=0;
static int64_t LM_HP=0;
static int64_t lm_anew(int64_t n){if(n<0)n=0; if(LM_HP+4+8*n>LM_CAP_BYTES||AHP+1+n>AHEAP_CAP){lm_out_of_heap();} LM_HP+=4+8*n; int64_t h=AHP; AHEAP[h]=n; for(int64_t i=0;i<n;i++)AHEAP[h+1+i]=0; AHP=AHP+1+n; return h;}
static int64_t lm_aget(int64_t a,int64_t i){int64_t len=AHEAP[a]; if(i<0||i>=len)return 0; return AHEAP[a+1+i];}
static void lm_aset(int64_t a,int64_t i,int64_t x){int64_t len=AHEAP[a]; if(i<0||i>=len)return; AHEAP[a+1+i]=x;}
static int64_t lm_alen(int64_t a){return AHEAP[a];}
static int64_t lm_alloc_bytes(int64_t num_bytes) {
  int64_t words = (num_bytes + 7) / 8;
  if (AHP + words > AHEAP_PHYS) { lm_out_of_heap(); }
  LM_HP += num_bytes;
  int64_t h = AHP;
  for (int64_t i = 0; i < words; i++) AHEAP[h + i] = 0;
  AHP += words;
  return (int64_t)&AHEAP[h];
}
static int64_t lm_alloc_sum(int64_t tag, int64_t payload) {
  if (LM_HP + 16 > LM_CAP_BYTES || AHP + 2 > AHEAP_CAP) { lm_out_of_heap(); }
  LM_HP += 16;
  int64_t h = AHP;
  AHEAP[h] = tag;
  AHEAP[h+1] = payload;
  AHP += 2;
  return (int64_t)&AHEAP[h];
}
static int64_t lm_concat(int64_t pa, int64_t pb) {
  int32_t la = *(int32_t*)pa;
  int32_t lb = *(int32_t*)pb;
  int64_t ptr = lm_alloc_bytes(4 + la + lb);
  *(int32_t*)ptr = la + lb;
  memcpy((char*)ptr + 4, (char*)pa + 4, la);
  memcpy((char*)ptr + 4 + la, (char*)pb + 4, lb);
  return ptr;
}
static int64_t lm_int2text(int64_t val_s) {
  uint64_t v = (uint64_t)val_s;
  int32_t neg = 0;
  if (val_s < 0) {
    neg = 1;
    v = 0 - v;
  }
  int32_t nd = 1;
  uint64_t tmp = v;
  while (1) {
    tmp = tmp / 10;
    if (tmp == 0) break;
    nd++;
  }
  int32_t len = nd + neg;
  int64_t ptr = lm_alloc_bytes(4 + len);
  *(int32_t*)ptr = len;
  char* w = (char*)ptr + 4 + len;
  uint64_t curr = v;
  while (1) {
    w--;
    *w = (char)(48 + (curr % 10));
    curr = curr / 10;
    if (curr == 0) break;
  }
  if (neg) {
    *((char*)ptr + 4) = '-';
  }
  return ptr;
}
static int64_t lm_dec_mul(int64_t a, int64_t b) {
  int neg = 0;
  __int128 sa = a, sb = b;
  if (sa < 0) { neg ^= 1; sa = -sa; }
  if (sb < 0) { neg ^= 1; sb = -sb; }
  __int128 prod = sa * sb;
  __int128 q = prod / 1000000;
  __int128 r = prod % 1000000;
  if (r * 2 > 1000000) { q += 1; }
  else if (r * 2 == 1000000 && (q & 1)) { q += 1; }
  if (q > (__int128)INT64_MAX) { fflush(stdout); abort(); }
  int64_t result = (int64_t)q;
  return neg ? -result : result;
}
static int64_t lm_dec_div(int64_t a, int64_t b) {
  if (b == 0) { fflush(stdout); abort(); }
  int neg = 0;
  __int128 sa = a, sb = b;
  if (sa < 0) { neg ^= 1; sa = -sa; }
  if (sb < 0) { neg ^= 1; sb = -sb; }
  __int128 num = sa * (__int128)1000000;
  __int128 q = num / sb;
  __int128 r = num % sb;
  if (r * 2 > sb) { q += 1; }
  else if (r * 2 == sb && (q & 1)) { q += 1; }
  if (q > (__int128)INT64_MAX) { fflush(stdout); abort(); }
  int64_t result = (int64_t)q;
  return neg ? -result : result;
}
static int64_t lm_dec2text(int64_t v) {
  int32_t neg = 0;
  uint64_t uv;
  if (v < 0) { neg = 1; uv = (uint64_t)(-(__int128)v); } else { uv = (uint64_t)v; }
  uint64_t ip = uv / 1000000;
  uint64_t fp = uv % 1000000;
  int32_t nd = 1;
  uint64_t tmp = ip;
  while (1) { tmp = tmp / 10; if (tmp == 0) break; nd++; }
  int32_t flen = 6;
  uint64_t probe = fp;
  while (flen > 1) { if (probe % 10 != 0) break; probe = probe / 10; flen--; }
  int32_t len = neg + nd + 1 + flen;
  int64_t ptr = lm_alloc_bytes(4 + len);
  *(int32_t*)ptr = len;
  char* w = (char*)ptr + 4 + len;
  {
    uint64_t fw = probe;
    for (int32_t i = 0; i < flen; i++) { w--; *w = (char)(48 + (int)(fw % 10)); fw = fw / 10; }
  }
  w--; *w = '.';
  {
    uint64_t iw = ip;
    for (int32_t i = 0; i < nd; i++) { w--; *w = (char)(48 + (int)(iw % 10)); iw = iw / 10; }
  }
  if (neg) { *((char*)ptr + 4) = '-'; }
  return ptr;
}
static int64_t lm_texteq(int64_t pa, int64_t pb) {
  if (pa == pb) return 1;
  if (!pa || !pb) return 0;
  int32_t la = *(int32_t*)pa;
  int32_t lb = *(int32_t*)pb;
  if (la != lb) return 0;
  return memcmp((char*)pa + 4, (char*)pb + 4, la) == 0 ? 1 : 0;
}
static void lm_printtext(int64_t a) {
  if (!a) return;
  int32_t len = *(int32_t*)a;
  fwrite((char*)a + 4, 1, len, stdout);
}
static int64_t lm_read_file(int64_t path_ptr) {
  if (!path_ptr) { int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  int32_t plen = *(int32_t*)path_ptr;
  char* path = (char*)malloc(plen + 1);
  if (!path) { int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  memcpy(path, (char*)path_ptr + 4, plen);
  path[plen] = '\0';
  char mode[3]; mode[0] = 114; mode[1] = 98; mode[2] = 0;
  FILE* f = fopen(path, mode);
  free(path);
  if (!f) { int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz < 0) sz = 0;
  int64_t ptr = lm_alloc_bytes(4 + sz);
  *(int32_t*)ptr = (int32_t)sz;
  if (sz > 0) {
    size_t nread = fread((char*)ptr + 4, 1, sz, f);
    (void)nread;
  }
  fclose(f);
  return ptr;
}
static int64_t lm_read_line(int64_t path_ptr) {
  if (!path_ptr) { int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  int32_t plen = *(int32_t*)path_ptr;
  char* path = (char*)malloc(plen + 1);
  if (!path) { int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  memcpy(path, (char*)path_ptr + 4, plen);
  path[plen] = '\0';
  char mode2[3]; mode2[0] = 114; mode2[1] = 98; mode2[2] = 0;
  FILE* f = fopen(path, mode2);
  free(path);
  if (!f) { int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz < 0) sz = 0;
  char* buf = (char*)malloc(sz + 1);
  if (!buf) { fclose(f); int64_t ptr = lm_alloc_bytes(4); *(int32_t*)ptr = 0; return ptr; }
  size_t nread = fread(buf, 1, sz, f);
  fclose(f);
  int32_t line_len = 0;
  while (line_len < (int32_t)nread && buf[line_len] != 10 && buf[line_len] != 13) {
    line_len++;
  }
  int64_t ptr = lm_alloc_bytes(4 + line_len);
  *(int32_t*)ptr = line_len;
  if (line_len > 0) memcpy((char*)ptr + 4, buf, line_len);
  free(buf);
  return ptr;
}
